with target as(select * from public.works where id=any(array[3594,2599,240,2612,1416,552,2604,732]::bigint[]) or open_library_id=any(array['OL20884418W','OL457179W','OL81623W','OL457175W','OL176092W','OL76972W','OL15212619W','OL15424701W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['goodvibesgoodlife','middernachtskinderen','midnightschildren','ogenvanvuur','firestarter','deduivelsverzen','thesatanicverses','demaansteen','themoonstone','advocaatvandeduivel','thefirm','kamer','room','deeerstedag','oneday']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['goodvibesgoodlife','middernachtskinderen','midnightschildren','ogenvanvuur','firestarter','deduivelsverzen','thesatanicverses','demaansteen','themoonstone','advocaatvandeduivel','thefirm','kamer','room','deeerstedag','oneday']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL8112375A','OL26769A','OL19981A','OL22358A','OL39329A','OL70699A','OL1434926A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['vexking','salmanrushdie','rushdiesalman','srushdie','stephenking','kingstephenschriftsteller','wilkiecollins','williamwilkiecollins','wwilkiecollins','wilkiewcollins','johngrisham','jgrisham','johngrishamauthor','john10','emmadonoghue','emmadonoghueltd','donoghueemma','davidnicholls','nichollsdavid']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL42058445M','OL32125440M','OL32369988M','OL32945401M','OL24376841M','OL33219753M','OL33219930M','OL26201138M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789021574776','9789025457389','9789024551873','9789025434717','9789029512695','9789044927115','9789045823690','9789022554999']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
